template <typename T>
void sink(T&& t) { /* Lvalue/Rvalue received */ }

// Variadic template wrapper using perfect forwarding
template <typename... Args>
void func_wrapper(Args&&... args)
{
    // Args&&...: Forwarding References (Universal References)
    // Deduction: Lvalue -> T becomes T&; Rvalue -> T remains T
    // std::forward<Args> converts back to original category
    sink(std::forward<Args>(args)...);
}

